/* 801BAF18-801BAFCC       .text _open_wallPaper__12dMenu_Fmap_cFv */
bool dMenu_Fmap_c::_open_wallPaper() {
    if (mFrameTimer == 0) {
        mButtonIconMode = FMAP_BTN_ICON_WALLPAPER;
        selCursorHide();
    }
    BOOL ret = paneTransBase(mFrameTimer, g_mfHIO.field_0x34, g_mfHIO.field_0x36, 0.0, 0, 1);
    mFrameTimer++;
    if (ret == 1) {
        mFrameTimer = 0;
        mFmapMode = FMAP_MODE_WALLPAPER;
        return TRUE;
    }
    return FALSE;
}

